  40:     private final Map<Class<?>, Provider<OverlayViewMediator>>
  41:             mContentMediatorCreators;
  42:     private final OverlayViewGlobalStateController mOverlayViewGlobalStateController;
  43: 
  44:     @Inject
  45:     public SystemUIOverlayWindowManager(
  46:             Context context,
  47:             Map<Class<?>, Provider<OverlayViewMediator>> contentMediatorCreators,
  48:             OverlayViewGlobalStateController overlayViewGlobalStateController) {
  49:         super(context);
  50:         mContentMediatorCreators = contentMediatorCreators;
  51:         mOverlayViewGlobalStateController = overlayViewGlobalStateController;
  52:     }
  53: 
  54:     @Override
  55:     public void start() {
  56:         String[] names = mContext.getResources().getStringArray(
  57:                 R.array.config_carSystemUIOverlayViewsMediators);
  58:         startServices(names);
  59:     }
  60: 
  61:     private void startServices(String[] services) {
  62:         for (String clsName : services) {
  63:             long ti = System.currentTimeMillis();
  64:             try {
  65:                 OverlayViewMediator obj = resolveContentMediator(clsName);
  66:                 if (obj == null) {
  67:                     Constructor constructor = Class.forName(clsName).getConstructor(Context.class);
  68:                     obj = (OverlayViewMediator) constructor.newInstance(this);
  69:                 }
  70:                 mOverlayViewGlobalStateController.registerMediator(obj);
  71:             } catch (ClassNotFoundException
  72:                     | NoSuchMethodException
  73:                     | IllegalAccessException
  74:                     | InstantiationException
  75:                     | InvocationTargetException ex) {
  76:                 throw new RuntimeException(ex);
  77:             }
  78: 
  79:             // Warn if initialization of component takes too long
  80:             ti = System.currentTimeMillis() - ti;
  81:             if (ti > 200) {
  82:                 Log.w(TAG, "Initialization of " + clsName + " took " + ti + " ms");
  83:             }
  84:         }
  85:     }
  86: 
  87:     private OverlayViewMediator resolveContentMediator(String className) {
  88:         return resolve(className, mContentMediatorCreators);
  89:     }
  90: 
  91:     private <T> T resolve(String className, Map<Class<?>, Provider<T>> creators) {
  92:         try {
  93:             Class<?> clazz = Class.forName(className);
  94:             Provider<T> provider = creators.get(clazz);
  95:             return provider == null ? null : provider.get();
  96:         } catch (ClassNotFoundException e) {
  97:             return null;
  98:         }
  99:     }
 100: }
