  62:     private Map<String, View> mStatusIconViewClassMap;
  63: 
  64:     public StatusIconGroupContainerController(
  65:             Context context,
  66:             @Main Resources resources,
  67:             CarServiceProvider carServiceProvider,
  68:             BroadcastDispatcher broadcastDispatcher,
  69:             ConfigurationController configurationController,
