  83: 
  84:     private static <T> T resolve(String className, Map<Class<?>, Provider<T>> creators) {
  85:         try {
  86:             Class<?> clazz = Class.forName(className);
  87:             Provider<T> provider = creators.get(clazz);
  88:             return provider == null ? null : provider.get();
  89:         } catch (ClassNotFoundException e) {
  90:             return null;
  91:         }
  92:     }
  93: 
  94:     /**
  95:      * Returns the layout res id to use as the button view that contains the StatusIcon.
