  99:         return R.layout.default_status_icon;
 100:     }
 101: 
 102:     /**
 103:      * See {@link #addIconViews(ViewGroup, boolean)}
 104:      */
 105:     public void addIconViews(ViewGroup containerViewGroup) {
 106:         addIconViews(containerViewGroup, /* shouldAttachPanel= */ true);
 107:     }
 108: 
 109:     /**
 110:      * Adds Quick Control entry points to the provided container ViewGroup. Also attaches
 111:      * the Quick Control panel if it's specified and allowed.
 112:      */
 113:     public void addIconViews(ViewGroup containerViewGroup, boolean shouldAttachPanel) {
 114:         LayoutInflater li = LayoutInflater.from(mContext);
 115:         @ColorInt int iconNotHighlightedColor = mContext.getColor(
 116:                 R.color.status_icon_not_highlighted_color);
 117: 
 118:         for (String clsName : mStatusIconControllerNames) {
 119:             StatusIconController statusIconController = getStatusIconControllerByName(clsName);
 120:             View entryPointView = li.inflate(getButtonViewLayout(),
 121:                     containerViewGroup, /* attachToRoot= */ false);
 122:             entryPointView.setId(statusIconController.getId());
 123: 
 124:             ImageView statusIconView = entryPointView.findViewWithTag(mIconTag);
 125:             statusIconController.registerIconView(statusIconView);
 126:             statusIconView.setColorFilter(iconNotHighlightedColor);
 127: 
 128:             if (shouldAttachPanel
 129:                     && statusIconController.getPanelContentLayout() != PANEL_CONTENT_LAYOUT_NONE) {
 130:                 StatusIconPanelController panelController = new StatusIconPanelController(mContext,
 131:                         mCarServiceProvider, mBroadcastDispatcher, mConfigurationController);
 132:                 panelController.attachPanel(entryPointView,
 133:                         statusIconController.getPanelContentLayout(),
 134:                         statusIconController.getPanelWidth());
 135:                 mStatusIconPanelControllers.add(panelController);
 136:             }
 137:             containerViewGroup.addView(entryPointView);
 138:             mStatusIconViewClassMap.put(clsName, entryPointView);
 139:         }
 140:     }
 141: 
 142:     /** Gets the class name of the selected View. */
 143:     public String getClassNameOfSelectedView() {
 144:         for (String clsName : mStatusIconViewClassMap.keySet()) {
 145:             View statusIconView = mStatusIconViewClassMap.get(clsName);
 146:             if (statusIconView.isSelected()) {
 147:                 return clsName;
 148:             }
 149:         }
 150:         return null;
 151:     }
 152: 
 153:     /** Gets the View corresponding to the given class name. */
 154:     public View getViewFromClassName(String clsName) {
 155:         return mStatusIconViewClassMap.getOrDefault(clsName, null);
 156:     }
 157: 
 158:     /** Resets the cached Views. */
 159:     public void resetCache() {
 160:         for (StatusIconPanelController panelController : mStatusIconPanelControllers) {
 161:             panelController.destroyPanel();
 162:         }
 163:         mStatusIconPanelControllers.clear();
 164:         mStatusIconViewClassMap.clear();
 165:     }
