 169: 
 170:     private StatusIconController getStatusIconControllerByName(String className) {
 171:         try {
 172:             StatusIconController statusIconController = resolveStatusIconController(className);
 173:             if (statusIconController == null) {
 174:                 Constructor constructor = Class.forName(className).getConstructor(Context.class);
 175:                 statusIconController = (StatusIconController) constructor.newInstance(this);
 176:             }
 177: 
 178:             return statusIconController;
 179:         } catch (ClassNotFoundException
 180:                 | NoSuchMethodException
 181:                 | IllegalAccessException
 182:                 | InstantiationException
 183:                 | InvocationTargetException ex) {
 184:             throw new RuntimeException(ex);
 185:         }
 186:     }
 187: 
 188:     private StatusIconController resolveStatusIconController(String className) {
 189:         return resolve(className, mIconControllerCreators);
 190:     }
 191: 
 192:     @VisibleForTesting
 193:     public void setStatusIconViewClassMap(Map<String, View> statusIconViewClassMap) {
 194:         mStatusIconViewClassMap = statusIconViewClassMap;
 195:     }
 196: 
 197: }

